    content: mdContent,
    created_at: new Date(),
    metadata: {
      source_file: fileName,
      word_count: countWords(mdContent)
    }
  };

  // 保存文档基本信息
  saveToDatabase(documentData);

  // 创建Neo4j节点
  createGraphNode(documentData);

  // 提取段落和标题结构
  const sections = extractSections(parsedMD);

  // 处理每个段落/章节
  sections.forEach(section => {
    const sectionId = generateUUID();

    // 保存段落/章节
    saveToDatabase({
      id: sectionId,
      parent_id: documentId,
      title: section.title,
      content: section.content,
      content_type: "markdown_section",
      level: section.level
    });

    // 创建节点关系
    createGraphRelationship(documentId, sectionId, "CONTAINS");

    // 为重要段落生成向量嵌入
    if (isSignificantSection(section)) {
      generateEmbeddings(sectionId, "markdown_section");
    }
  });

  // 为整个文档生成向量嵌入
  generateEmbeddings(documentId, "markdown_document");
}
```

### 3. 关系映射与同步策略

#### 脑图到知识图谱的映射
- **节点映射**：脑图节点 → Neo4j概念节点
- **关系映射**：
  - 父子关系 → `CONTAINS`关系
  - 同级节点 → `RELATED_TO`关系
  - 交叉引用 → `REFERENCES`关系

#### MD笔记到知识图谱的映射
- **文档映射**：整个MD文档 → Neo4j文档节点
- **结构映射**：
  - 标题层级 → 嵌套`CONTAINS`关系
  - 内部链接 → `REFERENCES`关系
  - 标签/关键词 → `TAGGED_WITH`关系

#### 自动发现关系
```javascript
// 自动发现内容关系
async function discoverRelationships(newContentId) {
  // 1. 获取内容向量嵌入
  const contentEmbedding = await getContentEmbedding(newContentId);

  // 2. 查找相似内容
  const similarContent = await findSimilarContent(contentEmbedding, 0.75, 5);

  // 3. 创建相似度关系
  similarContent.forEach(similar => {
    createGraphRelationship(
      newContentId, 
      similar.id, 
      "SIMILAR_TO", 
      { score: similar.similarity }
    );
  });

  // 4. 分析引用和关键词匹配
  const references = extractReferences(newContentId);
  references.forEach(ref => {
    createGraphRelationship(
      newContentId, 
      ref.targetId, 
      "REFERENCES", 
      { context: ref.context }
    );
  });
}
```

