  // 获取所有子节点和关系
  const childRelations = await getNodeRelationships(conceptId, 'CONTAINS', 'outgoing');

  // 递归构建脑图结构
  function buildMindMapNode(node, relations) {
    const mindNode = {
      id: node.id,
      topic: node.title,
      expanded: true
    };

    // 添加子节点
    const childIds = relations
      .filter(rel => rel.source === node.id)
      .map(rel => rel.target);

    if (childIds.length > 0) {
      mindNode.children = [];

      for (const childId of childIds) {
        const childNode = nodeMap.get(childId);
        const childMindNode = buildMindMapNode(childNode, relations);
        mindNode.children.push(childMindNode);
      }
    }

    return mindNode;
  }

  // 构建完整脑图
  const mindMapData = {
    meta: {
      name: `Export-${rootNode.title}`,
      author: "Knowledge System Export",
      version: "1.0"
    },
    format: "node_array",
    data: buildMindMapNode(rootNode, childRelations)
  };

  return JSON.stringify(mindMapData, null, 2);
}
```

## 实施建议

### 1. 增量同步方案

对于大型脑图和笔记集合，建议使用增量同步:

1. **文件散列**: 维护每个文件的内容散列，仅处理变更文件
2. **节点ID映射**: 维护外部ID到系统ID的映射表
3. **变更检测**: 比对新旧版本，仅更新变更部分

### 2. 冷热数据处理

参考您之前关注的冷热数据分层存储策略:

1. **热数据** (频繁访问内容):
   - 保存在内存缓存或快速存储中
   - 包括活跃的脑图节点和最近编辑的笔记部分

2. **温数据** (中频访问):
   - 保存在主数据库中
   - 包括近期使用的概念和关联

3. **冷数据** (低频访问):
   - 移至低成本存储
   - 包括历史版本和不活跃内容

### 3. 实施时序

1. **第一阶段**: 基础导入功能
   - 实现基本的脑图JSON解析
   - 实现基本的MD文档解析
   - 建立初步图关系

2. **第二阶段**: 智能关联发现
   - 实现向量嵌入生成
   - 添加语义相似度计算
   - 自动发现潜在关系

3. **第三阶段**: 双向同步机制
   - 实现文件监控
   - 添加差异比较与合并
   - 支持系统到外部文件的导出

