### 2. 关键组件

#### 2.1 脑图数据采集器

```javascript
// 脑图数据采集器
class MindMapCollector {
  constructor(apiService) {
    this.apiService = apiService;
  }

  // 读取脑图文件
  async readMindMapFile(filePath) {
    try {
      const content = await fs.promises.readFile(filePath, 'utf-8');
      return JSON.parse(content);
    } catch (error) {
      console.error(`读取脑图文件失败: ${error.message}`);
      throw error;
    }
  }

  // 处理脑图数据
  async processMindMap(mindMapData, options = {}) {
    const { generateRelationships = true, embeddingModel = 'default' } = options;

    // 记录脑图元数据
    const metadata = {
      source: 'mindmap',
      format: mindMapData.format || 'jsmind',
      timestamp: new Date().toISOString(),
      version: mindMapData.meta?.version || '1.0'
    };

    // 注册脑图源
    const sourceId = await this.apiService.registerDataSource({
      type: 'mindmap',
      name: mindMapData.meta?.name || '未命名脑图',
      metadata
    });

    // 处理节点
    const rootNode = mindMapData.data;
    await this.processNode(rootNode,, sourceId, generateRelationships, embeddingModel);

    return {
      sourceId,
      nodeCount: this.nodeCount,
      relationshipCount: this.relationshipCount
    };
  }

  // 递归处理节点
  async processNode(node, parentId, sourceId, generateRelationships, embeddingModel) {
    // 创建节点记录
    const nodeData = {
      id: node.id,
      title: node.topic || node.text || '',
      content_type: 'mindmap_node',
      source_id: sourceId,
      parent_id: parentId,
      metadata: {
        position: node.direction || node.position,
        expanded: node.expanded !== false,
        style: node.style || {},
        custom_data: node.data || {}
      }
    };

    // 保存到API服务
    const savedNode = await this.apiService.createNode(nodeData);
    this.nodeCount++;

    // 创建父子关系
    if (parentId) {
      await this.apiService.createRelationship({
        source_id: parentId,
        target_id: node.id,
        type: 'CONTAINS',
        metadata: { source: 'mindmap_structure' }
      });
      this.relationshipCount++;
    }

    // 生成向量嵌入
    if (node.topic || node.text) {
      await this.apiService.generateEmbedding(node.id, embeddingModel);
    }

    // 处理子节点
    if (node.children && node.children.length > 0) {
      for (const child of node.children) {
        await this.processNode(child, node.id, sourceId, generateRelationships, embeddingModel);
      }
    }

    // 发现潜在关系
    if (generateRelationships) {
      await this.apiService.discoverRelationships(node.id);
    }
  }
}
```

#### 2.2 API服务接口

```javascript
// 中间层API服务
class KnowledgeAPIService {
  constructor(config) {
    this.dbService = new DatabaseService(config.database);
    this.graphService = new GraphService(config.neo4j);
    this.vectorService = new VectorService(config.vector);
  }

  // 注册数据源
  async registerDataSource(sourceInfo) {
    const sourceId = uuidv4();
    await this.dbService.insertDataSource({
      id: sourceId,
      ...sourceInfo,
      created_at: new Date()
    });
    return sourceId;
  }

  // 创建节点
  async createNode(nodeData) {
    // 存储到PostgreSQL
    const savedNode = await this.dbService.insertNode(nodeData);

    // 创建图谱节点
    await this.graphService.createNode({
      id: nodeData.id,
      labels: ['Content', 'MindMapNode'],
      properties: {
        title: nodeData.title,
        content_type: nodeData.content_type,
        source_id: nodeData.source_id
      }
    });

    return savedNode;
  }

  // 创建关系
  async createRelationship(relationshipData) {
    // 存储关系元数据
    const relationshipId = uuidv4();
    await this.dbService.insertRelationship({
      id: relationshipId,
      ...relationshipData,
      created_at: new Date()
    });

    // 创建图谱关系
    await this.graphService.createRelationship({
      source_id: relationshipData.source_id,
      target_id: relationshipData.target_id,
      type: relationshipData.type,
      properties: relationshipData.metadata || {}
    });

    return relationshipId;
  }

  // 生成向量嵌入
  async generateEmbedding(nodeId, modelName = 'default') {
    // 获取节点内容
    const node = await this.dbService.getNodeById(nodeId);
    if (!node) throw new Error(`节点不存在: ${nodeId}`);

    // 生成文本向量
    const text = node.title + ' ' + (node.content || '');
    const embedding = await this.vectorService.generateEmbedding(text, modelName);

    // 保存向量
    await this.dbService.updateNodeEmbedding(nodeId, embedding);
    await this.vectorService.indexDocument({
      id: nodeId,
      embedding: embedding,
      metadata: {
        title: node.title,
        content_type: node.content_type
      }
    });

    return embedding;
  }

  // 发现关系
  async discoverRelationships(nodeId, options = {}) {
    const { similarityThreshold = 0.75, maxRelationships = 5 } = options;

    // 获取节点向量
    const node = await this.dbService.getNodeWithEmbedding(nodeId);
    if (!node || !node.embedding) {
      console.log(`节点 ${nodeId} 没有向量嵌入，跳过关系发现`);
      return [];
    }

    // 查找相似节点
    const similarNodes = await this.vectorService.findSimilar({
      embedding: node.embedding,
      threshold: similarityThreshold,
      limit: maxRelationships,
      exclude: [nodeId]
    });

    // 创建相似关系
    const relationships = [];
    for (const similar of similarNodes) {
      const relationshipData = {
        source_id: nodeId,
        target_id: similar.id,
        type: 'SIMILAR_TO',
        metadata: {
          similarity: similar.score,
          discovered: true,
          created_at: new Date()
        }
      };

      const relationshipId = await this.createRelationship(relationshipData);
      relationships.push({
        id: relationshipId,
        ...relationshipData
      });
    }

    return relationships;
  }
}
```

