### 2. 关键组件

#### 2.1 关系扩展器

```javascript
// 脑图关系扩展器
class MindMapRelationshipExpander {
  constructor(apiService) {
    this.apiService = apiService;
  }

  // 获取节点的相关关系
  async getNodeRelationships(nodeId, options = {}) {
    const {
      relationshipTypes = ['SIMILAR_TO', 'REFERENCES', 'RELATES_TO'],
      maxDepth = 1,
      maxNodes = 20,
      includeProperties = true
    } = options;

    // 查询关系数据
    const relationships = await this.apiService.getNodeRelationships(
      nodeId,
      relationshipTypes,
      maxDepth,
      maxNodes
    );

    // 获取相关节点信息
    const nodeIds = new Set();
    nodeIds.add(nodeId); // 添加中心节点

    // 收集所有关联节点ID
    relationships.forEach(rel => {
      nodeIds.add(rel.source_id);
      nodeIds.add(rel.target_id);
    });

    // 获取节点详情
    const nodes = await this.apiService.getNodesByIds(Array.from(nodeIds));

    return {
      centralNodeId: nodeId,
      nodes,
      relationships
    };
  }

  // 将关系转换为脑图格式
  convertRelationshipsToMindMap(relationshipData, options = {}) {
    const {
      centralNodeId,
      nodes,
      relationships
    } = relationshipData;

    const {
      positionMapping = {
        'SIMILAR_TO': 'right',
        'REFERENCES': 'left',
        'RELATES_TO': 'bottom',
        'DERIVED_FROM': 'top',
        'CONTRADICTS': 'bottom-right'
      },
      colorMapping = {
        'SIMILAR_TO': '#36a3eb',
        'REFERENCES': '#4ecb73',
        'RELATES_TO': '#dfa53a',
        'DERIVED_FROM': '#8c5ad6',
        'CONTRADICTS': '#eb5252'
      }
    } = options;

    // 查找中心节点
    const centralNode = nodes.find(n => n.id === centralNodeId);
    if (!centralNode) {
      throw new Error(`未找到中心节点: ${centralNodeId}`);
    }

    // 构建脑图根节点
    const rootNode = {
      id: centralNode.id,
      topic: centralNode.title,
      direction: 'center',
      expanded: true,
      children: []
    };

    // 添加自定义样式
    if (centralNode.metadata && centralNode.metadata.style) {
      rootNode.style = centralNode.metadata.style;
    } else {
      rootNode.style = {
        'background-color': '#3498db',
        'color': '#ffffff'
      };
    }

    // 按关系类型分组
    const relationshipsByType = {};
    relationships.forEach(rel => {
      if (!relationshipsByType[rel.type]) {
        relationshipsByType[rel.type] = [];
      }
      relationshipsByType[rel.type].push(rel);
    });

    // 为每种关系类型创建分组节点
    Object.entries(relationshipsByType).forEach(([type, rels]) => {
      // 确定方向
      const direction = positionMapping[type] || 'right';

      // 创建关系类型分组节点
      const typeNode = {
        id: `group_${centralNodeId}_${type}`,
        topic: formatRelationType(type),
        direction: direction,
        children: [],
        expanded: true,
        style: {
          'background-color': colorMapping[type] || '#7e7e7e',
          'color': '#ffffff'
        }
      };

      // 添加关系节点
      rels.forEach(rel => {
        // 确定目标节点（非中心节点的那个）
        const targetId = rel.source_id === centralNodeId ? rel.target_id : rel.source_id;
        const targetNode = nodes.find(n => n.id === targetId);

        if (targetNode) {
          const childNode = {
            id: targetNode.id,
            topic: targetNode.title,
            direction: direction,
            data: {
              original_type: targetNode.content_type,
              relationship_type: type,
              relationship_id: rel.id,
              similarity: rel.metadata?.similarity
            }
          };

          // 添加关系属性信息
          if (rel.metadata && Object.keys(rel.metadata).length > 0) {
            // 将关系属性格式化为工具提示
            const tooltipContent = Object.entries(rel.metadata)
              .filter(([k, v]) => k !== 'style' && k !== 'created_at')
              .map(([k, v]) => `${formatPropertyName(k)}: ${formatPropertyValue(v)}`)
              .join('\n');

            childNode.data.tooltip = tooltipContent;
          }

          typeNode.children.push(childNode);
        }
      });

      // 只有当有子节点时才添加分组节点
      if (typeNode.children.length > 0) {
        rootNode.children.push(typeNode);
      }
    });

    // 构建完整脑图结构
    const mindMapData = {
      meta: {
        name: `关系视图: ${centralNode.title}`,
        author: "Knowledge System",
        version: "1.0"
      },
      format: "node_tree",
      data: rootNode
    };

    return mindMapData;
  }

  // 辅助函数：格式化关系类型名称
  formatRelationType(type) {
    const mapping = {
      'SIMILAR_TO': '相似概念',
      'REFERENCES': '引用关系',
      'RELATES_TO': '相关内容',
      'CONTAINS': '包含关系',
      'DERIVED_FROM': '衍生自',
      'CONTRADICTS': '存在矛盾'
    };

    return mapping[type] || type;
  }
}
```

#### 2.2 脑图更新器

```javascript
// 脑图更新服务
class MindMapUpdater {
  constructor(apiService) {
    this.apiService = apiService;
    this.expander = new MindMapRelationshipExpander(apiService);
  }

  // 创建关系视图
  async createRelationshipView(nodeId, options = {}) {
    // 获取节点关系
    const relationshipData = await this.expander.getNodeRelationships(nodeId, options);

    // 转换为脑图格式
    const mindMapData = this.expander.convertRelationshipsToMindMap(
      relationshipData,
      options
    );

    return mindMapData;
  }

  // 合并到现有脑图
  async mergeIntoExistingMindMap(existingMindMap, relationshipView, options = {}) {
    const {
      mergeBehavior = 'add_missing',  // 'add_missing', 'replace_all', 'smart_merge'
      preservePositions = true,
      preserveStyles = true
    } = options;

    // 获取现有节点映射
    const existingNodesMap = this.buildNodeMap(existingMindMap.data);

    // 合并策略
    if (mergeBehavior === 'replace_all') {
      // 完全替换中心节点的所有子节点
      const centralNodeId = relationshipView.data.id;
      if (existingNodesMap.has(centralNodeId)) {
        const existingNode = existingNodesMap.get(centralNodeId);
        existingNode.children = relationshipView.data.children;

        // 保留原始位置和样式
        if (preservePositions && existingNode.direction) {
          relationshipView.data.direction = existingNode.direction;
        }

        if (preserveStyles && existingNode.style) {
          relationshipView.data.style = existingNode.style;
        }
      }
    }
    else if (mergeBehavior === 'smart_merge') {
      // 智能合并 - 保留现有分组，添加新关系
      this.smartMergeNodes(existingMindMap.data, relationshipView.data, existingNodesMap);
    }
    else { // add_missing
      // 只添加缺失的节点
      this.addMissingNodes(existingMindMap.data, relationshipView.data, existingNodesMap);
    }

    return existingMindMap;
  }

  // 导出为JSMind格式文件
  async exportToJsMindFile(mindMapData, filePath) {
    try {
      await fs.promises.writeFile(
        filePath,
        JSON.stringify(mindMapData, null, 2),
        'utf-8'
      );
      return { success: true, path: filePath };
    } catch (error) {
      console.error(`导出脑图文件失败: ${error.message}`);
      throw error;
    }
  }

  // 构建节点映射
  buildNodeMap(rootNode) {
    const nodeMap = new Map();

    // 递归处理节点
    function processNode(node) {
      nodeMap.set(node.id, node);

      if (node.children && node.children.length > 0) {
        node.children.forEach(processNode);
      }
    }

    processNode(rootNode);
    return nodeMap;
  }

  // 智能合并节点
  smartMergeNodes(targetRoot, sourceRoot, existingNodesMap) {
    // 实现智能合并逻辑
