```javascript
// JSMind插件实现
(function($, jsMind) {
  // 定义插件
  jsMind.plugins = jsMind.plugins || {};
  jsMind.plugins.knowledgeGraph = {
    init: function(options) {
      this.options = options || {};
      this.apiEndpoint = options.apiEndpoint || '/api/knowledge';
      this.jm = null;

      // 注册扩展方法
      jsMind.prototype.importRelationships = this.importRelationships;
      jsMind.prototype.exportToKnowledgeGraph = this.exportToKnowledgeGraph;
      jsMind.prototype.showRelationships = this.showRelationships;

      // 添加UI元素
      this._addToolbarButtons();

      return this;
    },

    // 将当前脑图注入知识图谱
    exportToKnowledgeGraph: function() {
      const plugin = jsMind.plugins.knowledgeGraph;
      const mindData = this.get_data();

      return fetch(`${plugin.options.apiEndpoint}/mindmap/import`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json'
        },
        body: JSON.stringify(mindData)
      })
      .then(response => response.json())
      .then(result => {
        if (result.success) {
          alert(`成功导入脑图: ${result.nodeCount} 个节点, ${result.relationshipCount} 个关系`);
        } else {
          alert(`导入失败: ${result.error}`);
        }
        return result;
      })
      .catch(error => {
        console.error('导入脑图失败:', error);
        alert(`导入失败: ${error.message}`);
        throw error;
      });
    },

    // 显示指定节点的关系
    showRelationships: function(nodeId) {
      const plugin = jsMind.plugins.knowledgeGraph;
      const jm = this;

      // 如果未提供节点ID，使用当前选中节点
      if (!nodeId) {
        const selectedNode = jm.get_selected_node();
        if (!selectedNode) {
          alert('请先选择一个节点');
          return Promise.reject(new Error('未选择节点'));
        }
        nodeId = selectedNode.id;
      }

      // 获取节点关系
      return fetch(`${plugin.options.apiEndpoint}/relationships/view/${nodeId}`)
        .then(response => response.json())
        .then(mindMapData => {
          // 合并或替换现有脑图
          if (plugin.options.replaceCurrent) {
            // 替换整个脑图
            jm.show(mindMapData);
          } else {
            // 合并到现有脑图
            const currentData = jm.get_data();

            // 发送请求合并数据
            return fetch(`${plugin.options.apiEndpoint}/mindmap/merge`, {
              method: 'POST',
              headers: {
                'Content-Type': 'application/json'
              },
              body: JSON.stringify({
                existing: currentData,
                relationships: mindMapData,
                options: {
                  mergeBehavior: plugin.options.mergeBehavior || 'add_missing'
                }
              })
            })
            .then(response => response.json())
            .then(mergedData => {
              jm.show(mergedData);
              return mergedData;
            });
          }

          return mindMapData;
        })
        .catch(error => {
          console.error('获取关系视图失败:', error);
          alert(`获取关系失败: ${error.message}`);
          throw error;
        });
    },

    // 添加工具栏按钮
    _addToolbarButtons: function() {
      const plugin = this;

      // 在DOM加载完成后添加
      $(document).ready(function() {
        const toolbar = $('.jsmind-toolbar');
        if (toolbar.length > 0) {
          // 添加导入按钮
          $('<button>')
            .addClass('jsmind-toolbar-button export-kg')
            .attr('title', '导入到知识图谱')
            .html('<span class="icon">🧠</span>')
            .click(function() {
              const jm = jsMind.current;
              if (jm) {
                jm.exportToKnowledgeGraph();
              }
            })
            .appendTo(toolbar);

          // 添加关系按钮
          $('<button>')
            .addClass('jsmind-toolbar-button show-relations')
            .attr('title', '显示相关节点')
            .html('<span class="icon">🔄</span>')
            .click(function() {
              const jm = jsMind.current;
              if (jm) {
                jm.showRelationships();
              }
            })
            .appendTo(toolbar);
        }
      });
    }
  };
})(jQuery, jsMind);

