## 关系栏功能建议

### 1. 核心功能

```javascript
// 关系视图核心实现
class RelationshipView {
  constructor(containerId, options = {}) {
    this.container = document.getElementById(containerId);
    this.options = Object.assign({
      width: 500,
      height: 400,
      nodeSize: 8,
      linkDistance: 100,
      colors: {
        node: "#69b3a2",
        link: "#ddd",
        highlight: "#ff7700"
      }
    }, options);

    this.svg = d3.select(this.container)
      .append("svg")
      .attr("width", this.options.width)
      .attr("height", this.options.height);

    this.createForces();
    this.setupEventHandlers();
  }

  // 展示指定节点的关系网络
  displayRelationships(nodeId, depth = 1) {
    // 从Neo4j获取关系数据
    fetchRelationshipData(nodeId, depth)
      .then(data => {
        this.renderGraph(data);
      });
  }

  // 渲染关系图
  renderGraph(data) {
    const { nodes, links } = data;

    // 清除现有内容
    this.svg.selectAll("*").remove();

    // 添加箭头定义
    this.defineArrowMarkers();

    // 创建力导向模拟
    const simulation = d3.forceSimulation(nodes)
      .force("link", d3.forceLink(links).id(d => d.id).distance(this.options.linkDistance))
      .force("charge", d3.forceManyBody().strength(-300))
      .force("center", d3.forceCenter(this.options.width / 2, this.options.height / 2));

    // 绘制连接线
    const link = this.svg.append("g")
      .selectAll("path")
      .data(links)
      .enter().append("path")
      .attr("class", d => `link ${d.type}`)
      .attr("marker-end", d => `url(#arrow-${d.type})`)
      .attr("stroke", d => this.getLinkColor(d.type));

    // 绘制关系标签
    const linkText = this.svg.append("g")
      .selectAll("text")
      .data(links)
      .enter().append("text")
      .attr("class", "link-label")
      .text(d => this.formatRelationType(d.type));

    // 绘制节点
    const node = this.svg.append("g")
      .selectAll("circle")
      .data(nodes)
      .enter().append("circle")
      .attr("r", d => this.getNodeSize(d))
      .attr("fill", d => this.getNodeColor(d))
      .call(this.dragBehavior(simulation));

    // 节点文本
    const nodeText = this.svg.append("g")
      .selectAll("text")
      .data(nodes)
      .enter().append("text")
      .attr("class", "node-label")
      .attr("dy", -10)
      .text(d => d.title || d.id);

    // 更新函数
    simulation.on("tick", () => {
      // 更新链接位置
      link.attr("d", d => {
        const dx = d.target.x - d.source.x,
              dy = d.target.y - d.source.y,
              dr = Math.sqrt(dx * dx + dy * dy) * 1.5;
        return `M${d.source.x},${d.source.y}A${dr},${dr} 0 0,1 ${d.target.x},${d.target.y}`;
      });

      // 更新链接标签位置
      linkText
        .attr("x", d => (d.source.x + d.target.x) / 2)
        .attr("y", d => (d.source.y + d.target.y) / 2 - 5);

      // 更新节点位置
      node
        .attr("cx", d => d.x)
        .attr("cy", d => d.y);

      // 更新节点文本位置
      nodeText
        .attr("x", d => d.x)
        .attr("y", d => d.y);
    });
  }

  // 其他辅助方法...
}
```

