```javascript
// 数据同步器
class DataSynchronizer {
  constructor(neoService) {
    this.neoService = neoService;
    this.setupEventListeners();
  }

  setupEventListeners() {
    // 监听转换到脑图事件
    EventBus.on('convert_to_mindmap', async (data) => {
      try {
        // 1. 获取关系数据
        const relationshipData = await this.neoService.getRelationshipData(
          data.sourceNodeId, 
          data.depth, 
          data.relationTypes
        );

        // 2. 转换为脑图格式
        const mindMapData = this.convertToMindMapFormat(
          relationshipData, 
          data.layout
        );

        // 3. 触发脑图更新事件
        EventBus.emit('update_mindmap', mindMapData);
      } catch (error) {
        console.error('转换到脑图失败:', error);
        EventBus.emit('show_error', {
          message: '无法加载关系数据',
          details: error.message
        });
      }
    });

    // 监听设置脑图中心事件
    EventBus.on('set_mindmap_center', async (data) => {
      try {
        // 获取节点详情
        const nodeDetails = await this.neoService.getNodeDetails(data.nodeId);

        // 设置为脑图中心
        EventBus.emit('center_mindmap', {
          node: nodeDetails
        });
      } catch (error) {
        console.error('设置脑图中心失败:', error);
      }
    });

    // 监听添加到脑图事件
    EventBus.on('add_to_mindmap', async (data) => {
      try {
        // 获取节点详情
        const nodeDetails = await this.neoService.getNodeDetails(data.nodeId);

        // 添加到脑图
        EventBus.emit('add_node_to_mindmap', {
          node: nodeDetails,
          parent: data.parentId || null,
          position: data.position || 'auto'
        });
      } catch (error) {
        console.error('添加到脑图失败:', error);
      }
    });
  }

  // 将关系数据转换为脑图格式
  convertToMindMapFormat(relationshipData, layout) {
    const { nodes, links } = relationshipData;
    const centerNodeId = relationshipData.centralNodeId;
    const centerNode = nodes.find(n => n.id === centerNodeId);

    if (!centerNode) {
      throw new Error('中心节点不存在');
    }

    // 创建脑图根节点
    const rootNode = {
      id: centerNode.id,
      topic: centerNode.title || centerNode.name,
      direction: 'center',
      data: {
        nodeType: centerNode.type,
        properties: centerNode.properties
      }
    };

    // 分析关系，按类型分组
    const relationshipsByType = {};
    links.forEach(link => {
      if (!relationshipsByType[link.type]) {
        relationshipsByType[link.type] = [];
      }
      relationshipsByType[link.type].push(link);
    });

    // 决定节点方向
    const directions = this.calculateNodeDirections(layout, Object.keys(relationshipsByType));

    // 为根节点添加子节点
    rootNode.children = [];

    // 按关系类型创建分组
    Object.entries(relationshipsByType).forEach(([type, links], index) => {
      // 确定此关系类型的方向
      const direction = directions[index % directions.length];

      // 创建关系类型分组节点
      const typeNode = {
        id: `group_${centerNodeId}_${type}`,
        topic: this.formatRelationType(type),
        direction: direction,
        data: {
          isGroup: true,
          relationType: type
        },
        children: []
      };

      // 添加关系节点
      links.forEach(link => {
        // 确定目标节点（非中心节点的那一端）
        const targetId = link.source === centerNodeId ? link.target : link.source;
        const targetNode = nodes.find(n => n.id === targetId);

        if (targetNode) {
          typeNode.children.push({
            id: targetNode.id,
            topic: targetNode.title || targetNode.name,
            direction: direction,
            data: {
              nodeType: targetNode.type,
              properties: targetNode.properties,
              relationshipId: link.id,
              relationshipProperties: link.properties
            }
          });
        }
      });

      // 只有当有子节点时才添加分组节点
      if (typeNode.children.length > 0) {
        rootNode.children.push(typeNode);
      }
    });

    return {
      format: 'node_tree',
      data: rootNode
    };
  }

  // 计算节点方向
  calculateNodeDirections(layout, relationTypes) {
    if (layout === 'auto') {
      // 自动分配方向
      const directions = [];
      const count = relationTypes.length;

      if (count <= 2) {
        directions.push('right', 'left');
      } else if (count <= 4) {
        directions.push('right', 'left', 'top', 'bottom');
      } else {
        directions.push('right', 'left', 'top', 'bottom');
        // 添加对角线方向
        directions.push('top-right', 'top-left', 'bottom-right', 'bottom-left');
      }

      return directions;
    } else {
      // 固定方向
      return [layout];
    }
  }

  // 格式化关系类型名称
  formatRelationType(type) {
    const mapping = {
      'SIMILAR_TO': '相似概念',
      'REFERENCES': '引用关系',
      'RELATES_TO': '相关内容',
      'CONTAINS': '包含关系',
      'DERIVED_FROM': '衍生自',
      'CONTRADICTS': '存在矛盾'
    };

    return mapping[type] || type;
  }
}
